```go
// HasExemplarAtOrAfter reports whether the given series has an exemplar with a
// timestamp at or after mint.
func (ce *CircularExemplarStorage) HasExemplarAtOrAfter(l labels.Labels, mint int64) bool {
	var buf [1024]byte
	seriesLabels := l.Bytes(buf[:])

	ce.lock.RLock()
	defer ce.lock.RUnlock()

	idx, ok := ce.index[string(seriesLabels)]
	if !ok {
		return false
	}
	// The per-series list is ordered by timestamp, so the newest exemplar has the highest timestamp.
	return ce.exemplars[idx.newest].exemplar.Ts >= mint
}
```

